def diagram(name, boxes, arrows, size=(1500,1000)):
 im=Image.new('RGB',size,'white'); d=ImageDraw.Draw(im); f=ImageFont.truetype(font,27)
 for i,(x,y,w,h,t) in enumerate(boxes):
  d.rounded_rectangle((x,y,x+w,y+h),radius=12,fill='#f2f5f8',outline='#263b4c',width=3)
  lines=t.split('\n'); yy=y+(h-len(lines)*35)/2
  for line in lines:
   bb=d.textbbox((0,0),line,font=f); d.text((x+(w-(bb[2]-bb[0]))/2,yy),line,font=f,fill='#17232c'); yy+=35
 for x1,y1,x2,y2 in arrows:
  d.line((x1,y1,x2,y2),fill='#263b4c',width=4)
  import math
  a=math.atan2(y2-y1,x2-x1); L=16
  d.polygon([(x2,y2),(x2-L*math.cos(a-.5),y2-L*math.sin(a-.5)),(x2-L*math.cos(a+.5),y2-L*math.sin(a+.5))],fill='#263b4c')
 im.save(A/f'{name}.png')
