def placeholder(n,cap,instruction):
 t=D.add_table(rows=1,cols=1);c=t.cell(0,0);c.text='МІСЦЕ ДЛЯ СКРІНШОТА\n\n'+instruction
 for q in c.paragraphs:q.paragraph_format.first_line_indent=0;q.alignment=WD_ALIGN_PARAGRAPH.LEFT;q.paragraph_format.space_after=Pt(12)
 pr=c._tc.get_or_add_tcPr();shade=OxmlElement('w:shd');shade.set(qn('w:fill'),'F2F2F2');pr.append(shade)
 D.add_paragraph(f'Рисунок {n} – {cap}',style='Caption')
def table(headers,rows,widths=None):
 t=D.add_table(rows=1,cols=len(headers));t.autofit=False
 if widths:
  for col,w in zip(t.columns,widths):col.width=Cm(w)
 for c,v in zip(t.rows[0].cells,headers):c.text=v
 for row in rows:
  for c,v in zip(t.add_row().cells,row):c.text=str(v)
 for ri,row in enumerate(t.rows):
  for ci,c in enumerate(row.cells):
   if widths:c.width=Cm(widths[ci])
   for q in c.paragraphs:
    q.paragraph_format.first_line_indent=0;q.alignment=WD_ALIGN_PARAGRAPH.LEFT;q.paragraph_format.space_after=Pt(4);q.paragraph_format.space_before=Pt(4);q.paragraph_format.line_spacing=1.05
    for r in q.runs:r.font.size=Pt(10.5);r.bold=ri==0
   pr=c._tc.get_or_add_tcPr();b=OxmlElement('w:tcBorders')
   for side in ['top','left','bottom','right']:
    e=OxmlElement('w:'+side);e.set(qn('w:val'),'single');e.set(qn('w:sz'),'4');e.set(qn('w:color'),'D9D9D9');b.append(e)
   pr.append(b)
   if ri==0:
    e=OxmlElement('w:shd');e.set(qn('w:fill'),'E8EDF2');pr.append(e)
  trpr=row._tr.get_or_add_trPr();trpr.append(OxmlElement('w:cantSplit'))
 t.rows[0]._tr.get_or_add_trPr().append(OxmlElement('w:tblHeader'))
 D.add_paragraph().paragraph_format.space_after=Pt(1)

